// ===== 1. INPUTS =====
const first = $input.first().json;
const parts = first?.candidates?.[0]?.content?.parts || [];
const aiText = (
  parts.filter(p => p.text && !p.thought).map(p => p.text).join('\n') ||
  first.text || ''
).trim();

let cvText = '', pages = 1, jd = '';
try { const e = $('Extract from File').first().json; cvText = String(e.text || ''); pages = e.numpages || 1; } catch (e) {}
try { jd = $('Webhook').first().json.body.jobDescription || ''; } catch (e) {}

// ===== 2. SECTION PARSER (plain headings + markdown) =====
const LABELS = {
  objective: 'objective|career objective',
  summary: 'summary|professional summary|profile|professional profile|about me',
  experience: 'experience|work experience|professional experience|employment history|employment|work history|internships?',
  education: 'education|academic background|qualifications',
  skills: 'skills|technical skills|key skills|core skills|technologies',
  projects: 'projects?|personal projects',
  certifications: 'certifications?|certificates|courses|training',
  name: 'name|full name',
  role: 'role|job title|title',
  stop: 'languages|interests|hobbies|references|awards'
};
const HEADS = Object.entries(LABELS).map(([k, v]) => [k, new RegExp('^(?:' + v + ')(?:\\s*[:\\-–—]\\s*|\\s*$)(.*)$', 'i')]);
const clean = l => l.replace(/[*_`#>|]/g, '').replace(/^\s*(?:[-•▪●]|\d+[.)])\s+/, '').trim();

function parse(text) {
  const out = {}; let cur = null;
  for (const raw of String(text || '').split(/\r?\n/)) {
    const line = clean(raw);
    if (!line) continue;
    let hit = null;
    for (const [k, re] of HEADS) { const m = line.match(re); if (m) { hit = [k, m[1].trim()]; break; } }
    if (hit) { cur = hit[0]; out[cur] = out[cur] || []; if (hit[1]) out[cur].push(hit[1]); }
    else if (cur) out[cur].push(line);
  }
  return out;
}

// ===== 3. AI + CV TEXT =====
const ai = parse(aiText), cv = parse(cvText);

// If Gemini returned JSON, it overrides the markdown parse
try {
  const m = aiText.match(/\{[\s\S]*\}/);
  const aj = m ? JSON.parse(m[0]) : null;
  if (aj) for (const k of ['name','role','objective','summary','experience','education','skills','projects','certifications']) {
    const hit = Object.entries(aj).find(([x]) => x.toLowerCase() === k);
    if (hit && hit[1] != null) ai[k] = [].concat(hit[1])
      .map(x => typeof x === 'string' ? x : Object.values(x).join(' — ')).filter(Boolean);
  }
} catch (e) {}

// CV text first (exactly what the user wrote), Gemini as fallback
const get = k => (cv[k] && cv[k].length ? cv[k] : ai[k]) || [];
const cvLines = cvText.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
const name = (ai.name && ai.name.join(' ')) || (cv.name && cv.name.join(' ')) || cvLines[0] || '';
const role = (ai.role && ai.role.join(' ')) || (cv.role && cv.role.join(' ')) || '';

const objective = get('objective').join(' ');
const summary = get('summary').join(' ');
const experience = get('experience');
const education = get('education');
const projects = get('projects');
const certifications = get('certifications');
const skillsList = [...new Set(get('skills').join(', ').split(/[,;|•]/).map(s => s.trim()).filter(s => s && s.length < 40))];

// ===== 4. ANALYSIS (score, skills, contact) =====
const t = cvText.replace(/\s+/g, ' ').trim();
const low = (t + ' ' + skillsList.join(' ')).toLowerCase();
const has = k => new RegExp('(^|[^a-z0-9])' + k.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '($|[^a-z0-9])').test(low);

const SK = {
  'Frontend': ['html','css','javascript','typescript','react','vue','angular','tailwind','next.js','bootstrap','sass','redux','framer motion'],
  'Backend': ['node','node.js','express','python','django','flask','java','spring','php','laravel','c#','.net','sql','mongodb','postgresql','mysql','supabase','rest','graphql','api'],
  'Cloud and DevOps': ['docker','kubernetes','aws','azure','gcp','git','github','ci/cd','linux','n8n','jenkins','terraform'],
  'Data and AI': ['machine learning','ai','nlp','tensorflow','pytorch','pandas','numpy','power bi','excel','tableau','llm','openai'],
  'Working style': ['leadership','communication','teamwork','problem solving','agile','scrum','management']
};
const skills = Object.entries(SK).map(([category, list]) => ({ category, items: list.filter(has) })).filter(g => g.items.length);
const skillCount = skills.reduce((n, g) => n + g.items.length, 0);
const words = (t.toLowerCase().match(/[a-z0-9+#.]{2,}/g) || []).length;

const contact = {
  email: /[\w.+-]+@[\w-]+\.[\w.]+/.test(t),
  phone: /\+?\d[\d\s-]{8,}\d/.test(t),
  linkedin: /linkedin/.test(low),
  github: /github/.test(low)
};

const SEC = {
  summary: /\b(summary|profile|objective|about me)\b/, experience: /\b(experience|employment|work history|internship)\b/,
  education: /\b(education|university|college|bachelor|master|degree|b\.?sc|m\.?sc)\b/, skills: /\b(skills|technologies|technical|competenc)/,
  projects: /\bprojects?\b/, certifications: /\b(certif|courses?|training)/
};
const W = { contact: 15, summary: 10, experience: 20, education: 15, skills: 15, projects: 10, certifications: 5 };
const found = { summary: summary || objective, experience: experience.length, education: education.length, skills: skillsList.length, projects: projects.length, certifications: certifications.length };
const sections = {}; let score = 0;
for (const k in W) {
  sections[k] = k === 'contact' ? (contact.email || contact.phone) : !!found[k] || SEC[k].test(low);
  if (sections[k]) score += W[k];
}
score += (words >= 250 && words <= 1000) ? 10 : (words >= 120 && words <= 1500) ? 5 : 0;
score = Math.min(100, score);

// ===== 5. JOB MATCH =====
const STOP = new Set('the and for you our will are have has your that this from able work working team years year experience strong good role job skills knowledge ability required preferred including using related across within must should plus etc such other more their they who what also can with not but all any new use used how why where when about into than then its was were been being does did'.split(' '));
let matchScore = null, missingKeywords = [];
if (jd.trim().length > 20) {
  const freq = {};
  (jd.toLowerCase().match(/[a-z][a-z0-9+#.]{2,}/g) || []).filter(w => !STOP.has(w)).forEach(w => freq[w] = (freq[w] || 0) + 1);
  const kws = Object.entries(freq).sort((a, b) => b[1] - a[1]).slice(0, 25).map(e => e[0]);
  const hit = kws.filter(has);
  matchScore = kws.length ? Math.round(hit.length / kws.length * 100) : null;
  missingKeywords = kws.filter(k => !hit.includes(k)).slice(0, 12);
}

// ===== 6. SUGGESTIONS =====
const S = [];
if (!t) S.push('No readable text found. Upload a text-based PDF, not a scan.');
if (!contact.email) S.push('Add a professional email address at the top.');
if (!contact.phone) S.push('Add a phone number so recruiters can call you.');
if (!contact.linkedin && !contact.github) S.push('Link your LinkedIn or GitHub profile.');
[['summary','Add a 2 to 3 line professional summary.'],['experience','Add an experience section with roles, dates and results.'],['education','Add your education.'],['skills','Add a dedicated skills section.'],['projects','Add 2 or 3 projects with what you built and the outcome.']]
  .forEach(([k, m]) => { if (!sections[k]) S.push(m); });
if ((t.match(/\d+\s?%|\$\s?\d+|\b\d{2,}\+?\b/g) || []).length < 3) S.push('Quantify your results, for example "cut load time by 40%".');
if (skillCount < 6) S.push('List more relevant tools and technologies.');
if (t && words < 250) S.push('Your CV is short. Expand on experience and projects.');
if (words > 1000) S.push('Your CV is long. Trim it to one or two pages.');
if (matchScore !== null && missingKeywords.length) S.push('Work these job keywords into your CV where true: ' + missingKeywords.slice(0, 6).join(', ') + '.');

// ===== 7. OUTPUT =====
return [{ json: {
  // fields used by the CV Lens page
  score,
  verdict: score >= 80 ? 'Strong CV' : score >= 60 ? 'Good, with room to improve' : 'Needs work',
  matchScore, skills, skillCount, sections, contact, missingKeywords,
  suggestions: S,
  stats: { words, pages, characters: t.length },
  preview: t.slice(0, 240),
  analyzedBy: 'n8n',
  // everything the user wrote in the CV
  name, role, objective, summary, experience, education, projects, certifications,
  skillsSection: skillsList.join(', '),
  aiSummary: aiText
} }];

